"""AWP 脚本共享库 — API 调用、钱包命令、ABI 编码、输入验证"""
from __future__ import annotations

import argparse
import json
import os
import re
import subprocess
import sys
import time
import urllib.request
import urllib.error
from decimal import Decimal
from pathlib import Path

_UINT256_MAX = 2**256 - 1

# ── 配置 ────────────────────────────────────────

API_BASE = os.environ.get("AWP_API_URL", "https://tapi.awp.sh/api")
RPC_URL = os.environ.get("EVM_RPC_URL", "https://mainnet.base.org")


# ── 输出 ────────────────────────────────────────

def info(msg: str) -> None:
    """输出 JSON 信息到 stderr"""
    print(json.dumps({"info": msg}), file=sys.stderr)


def step(name: str, **kwargs: object) -> None:
    """输出执行步骤到 stderr"""
    print(json.dumps({"step": name, **kwargs}), file=sys.stderr)


def die(msg: str) -> None:
    """输出错误到 stderr 并退出"""
    print(json.dumps({"error": msg}), file=sys.stderr)
    sys.exit(1)


# ── HTTP ────────────────────────────────────────

def api_get(path: str) -> dict | list | None:
    """GET {API_BASE}/{path}，返回解析后的 JSON"""
    url = f"{API_BASE}/{path.lstrip('/')}"
    try:
        req = urllib.request.Request(url, headers={"Accept": "application/json"})
        with urllib.request.urlopen(req, timeout=15) as resp:
            return json.loads(resp.read().decode())
    except (urllib.error.URLError, json.JSONDecodeError, OSError) as e:
        die(f"API request failed: {url} — {e}")
        return None  # unreachable


def api_post(url: str, body: dict) -> tuple[int, dict | str]:
    """POST JSON，返回 (http_code, parsed_body)"""
    data = json.dumps(body).encode()
    req = urllib.request.Request(
        url, data=data, method="POST",
        headers={"Content-Type": "application/json", "Accept": "application/json"},
    )
    try:
        with urllib.request.urlopen(req, timeout=30) as resp:
            return resp.status, json.loads(resp.read().decode())
    except urllib.error.HTTPError as e:
        body_str = e.read().decode() if e.fp else ""
        try:
            return e.code, json.loads(body_str)
        except json.JSONDecodeError:
            return e.code, body_str
    except (urllib.error.URLError, OSError) as e:
        die(f"POST failed: {url} — {e}")
        return 0, ""  # unreachable


def rpc_call(to: str, data: str) -> str:
    """eth_call via JSON-RPC，返回 hex result"""
    payload = {
        "jsonrpc": "2.0", "method": "eth_call",
        "params": [{"to": to, "data": data}, "latest"], "id": 1,
    }
    body = json.dumps(payload).encode()
    req = urllib.request.Request(
        RPC_URL, data=body, method="POST",
        headers={"Content-Type": "application/json"},
    )
    try:
        with urllib.request.urlopen(req, timeout=15) as resp:
            result = json.loads(resp.read().decode())
            # 检查 RPC 级别错误（revert 等）
            if "error" in result:
                err = result["error"]
                msg = err.get("message", err) if isinstance(err, dict) else err
                die(f"RPC error: {msg}")
            return result.get("result", "")
    except (urllib.error.URLError, json.JSONDecodeError, OSError) as e:
        die(f"RPC call failed: {e}")
        return ""  # unreachable


def hex_to_int(val: str) -> int:
    """将 hex 字符串转为 int，失败则 die"""
    if not val or val in ("null", "0x"):
        die("RPC returned empty/null value")
    return int(val, 16)


# ── 钱包命令 ─────────────────────────────────────

def wallet_cmd(args: list[str]) -> str:
    """执行 awp-wallet 命令，返回 stdout"""
    try:
        result = subprocess.run(
            ["awp-wallet"] + args,
            capture_output=True, text=True, timeout=60,
        )
    except subprocess.TimeoutExpired:
        die(f"awp-wallet {args[0]} timed out after 60s")
        return ""  # unreachable
    if result.returncode != 0:
        die(f"awp-wallet {args[0]} failed: {result.stderr.strip() or result.stdout.strip()}")
    return result.stdout.strip()


def get_wallet_address() -> str:
    """获取钱包地址（不需要 token），验证返回的地址格式"""
    out = wallet_cmd(["receive"])
    try:
        addr = json.loads(out).get("eoaAddress")
    except json.JSONDecodeError:
        die(f"Invalid wallet response: {out}")
        return ""  # unreachable
    if not addr or addr == "null":
        die("Wallet address is empty")
    if not ADDR_RE.match(addr):
        die(f"Wallet returned invalid address format: {addr}")
    return addr


def wallet_send(token: str, to: str, data: str, value: str = "0") -> str:
    """发送原始合约调用（calldata），返回结果 JSON。

    awp-wallet send 只支持代币转账，不支持 calldata。
    此函数通过 wallet-raw-call.mjs 桥接脚本调用 awp-wallet 内部签名模块。
    """
    bridge = str(Path(__file__).parent / "wallet-raw-call.mjs")
    args = ["node", bridge, "--token", token, "--to", to, "--data", data, "--value", value]
    try:
        result = subprocess.run(args, capture_output=True, text=True, timeout=120)
    except subprocess.TimeoutExpired:
        die("wallet-raw-call timed out after 120s")
        return ""  # unreachable
    if result.returncode != 0:
        die(f"wallet-raw-call failed: {result.stderr.strip() or result.stdout.strip()}")
    return result.stdout.strip()


def wallet_approve(token: str, asset: str, spender: str, amount: str) -> str:
    """授权代币，返回结果 JSON"""
    return wallet_cmd(["approve", "--token", token, "--asset", asset,
                        "--spender", spender, "--amount", amount])


def wallet_sign_typed_data(token: str, data: dict) -> str:
    """EIP-712 签名，返回 signature hex"""
    out = wallet_cmd(["sign-typed-data", "--token", token, "--data", json.dumps(data)])
    try:
        sig = json.loads(out).get("signature", "")
    except json.JSONDecodeError:
        die(f"Invalid sign response: {out}")
        return ""  # unreachable
    if not sig:
        die("Empty signature returned")
    return sig


def wallet_balance(token: str, asset: str | None = None) -> str:
    """查询余额"""
    args = ["balance", "--token", token]
    if asset:
        args += ["--asset", asset]
    return wallet_cmd(args)


def wallet_status(token: str) -> str:
    """查询钱包状态（地址、session 有效性）"""
    return wallet_cmd(["status", "--token", token])


# ── 合约注册表 ───────────────────────────────────

def get_registry() -> dict:
    """获取 /registry 并返回完整字典"""
    reg = api_get("registry")
    if not isinstance(reg, dict):
        die("Invalid /registry response")
    return reg


def require_contract(registry: dict, key: str) -> str:
    """从 registry 中获取合约地址，为空则 die"""
    addr = registry.get(key)
    if not addr or addr == "null":
        die(f"Failed to get {key} from /registry")
    return addr


# ── ABI 编码 ─────────────────────────────────────

def pad_address(addr: str) -> str:
    """将 0x 地址补齐为 64 字符（左补零），验证 hex 格式"""
    raw = addr.lower()
    if raw.startswith("0x"):
        raw = raw[2:]
    if not re.match(r"^[0-9a-f]+$", raw):
        die(f"pad_address: invalid hex characters in address: {addr}")
    if len(raw) > 64:
        die(f"pad_address: address too long after stripping 0x prefix: {addr}")
    return raw.zfill(64)


def pad_uint256(val: int) -> str:
    """将整数编码为 64 字符 hex（必须在 uint256 范围内）"""
    if val < 0 or val > _UINT256_MAX:
        die(f"pad_uint256: value out of uint256 range: {val}")
    return format(val, "064x")


def to_wei(human_amount: str) -> int:
    """人类可读 AWP 数量转 wei（使用 Decimal 避免浮点精度丢失）"""
    try:
        result = int(Decimal(human_amount) * Decimal(10**18))
    except (ValueError, TypeError, ArithmeticError) as e:
        die(f"to_wei: invalid amount: {human_amount} ({e})")
        return 0  # unreachable
    if result <= 0:
        die(f"to_wei: converted amount is zero (input: {human_amount})")
    return result


def days_to_seconds(days: str) -> int:
    """天数转秒数（使用 Decimal 避免浮点截断）"""
    try:
        result = int(Decimal(days) * Decimal(86400))
    except (ValueError, TypeError, ArithmeticError) as e:
        die(f"days_to_seconds: invalid input: {days} ({e})")
        return 0  # unreachable
    if result <= 0:
        die(f"days_to_seconds: result is zero (input: {days} days)")
    return result


def encode_calldata(selector: str, *params: str) -> str:
    """拼接 selector + 参数，验证 selector 格式（0x + 8 hex）"""
    if not re.match(r"^0x[0-9a-fA-F]{8}$", selector):
        die(f"encode_calldata: invalid selector format: {selector} (expected 0x + 8 hex chars)")
    return selector + "".join(params)


# ── 输入验证 ─────────────────────────────────────

ADDR_RE = re.compile(r"^0x[0-9a-fA-F]{40}$")


def validate_address(addr: str, name: str = "address") -> str:
    """验证以太坊地址格式"""
    if not ADDR_RE.match(addr):
        die(f"Invalid --{name}: must be 0x + 40 hex chars")
    return addr


def validate_positive_number(val: str, name: str = "amount") -> str:
    """验证正数（允许小数）"""
    if not re.match(r"^[0-9]+\.?[0-9]*$", val):
        die(f"Invalid --{name}: must be a positive number")
    if Decimal(val) <= 0:
        die(f"Invalid --{name}: must be > 0")
    return val


def validate_positive_int(val: str, name: str = "id") -> int:
    """验证正整数（uint256 范围内）"""
    if not re.match(r"^[0-9]+$", val):
        die(f"Invalid --{name}: must be a positive integer > 0")
    n = int(val)
    if n <= 0 or n > _UINT256_MAX:
        die(f"Invalid --{name}: must be > 0 and <= 2^256-1")
    return n


# ── EIP-712 构建 ─────────────────────────────────

def get_eip712_domain(registry: dict) -> dict:
    """从 registry 获取 EIP-712 domain 信息"""
    domain = registry.get("eip712Domain", {})
    name = domain.get("name")
    version = domain.get("version")
    chain_id = domain.get("chainId")
    contract = domain.get("verifyingContract")

    # fallback
    if not name:
        name = "AWPRegistry"
        version = "1"
        info("eip712Domain not in registry, using fallback")
    if not version:
        version = "1"
    if not chain_id:
        chain_id = registry.get("chainId")
    if not contract:
        contract = registry.get("awpRegistry")

    if not chain_id or not contract:
        die("Cannot determine EIP-712 domain from /registry")

    return {
        "name": name,
        "version": str(version),
        "chainId": int(chain_id),
        "verifyingContract": contract,
    }


def build_eip712(domain: dict, primary_type: str, type_fields: list[dict],
                 message: dict) -> dict:
    """构建完整 EIP-712 typed data"""
    return {
        "types": {
            "EIP712Domain": [
                {"name": "name", "type": "string"},
                {"name": "version", "type": "string"},
                {"name": "chainId", "type": "uint256"},
                {"name": "verifyingContract", "type": "address"},
            ],
            primary_type: type_fields,
        },
        "primaryType": primary_type,
        "domain": domain,
        "message": message,
    }


# ── 通用参数解析 ─────────────────────────────────

def base_parser(description: str) -> argparse.ArgumentParser:
    """创建带 --token 的基础参数解析器"""
    parser = argparse.ArgumentParser(description=description)
    parser.add_argument("--token", required=True, help="awp-wallet session token")
    return parser

#!/usr/bin/env bash
# On-chain subnet lifecycle — activate/pause/resume (V2)
# Usage:
#   ./onchain-subnet-lifecycle.sh --token <T> --subnet <id> --action <activate|pause|resume>
# Requires ETH for gas. SubnetNFT owner only.
# Pre-checks current subnet status to prevent invalid state transitions.
set -euo pipefail

API_BASE="${AWP_API_URL:-https://tapi.awp.sh/api}"
TOKEN=""
SUBNET=""
ACTION=""
while [[ $# -gt 0 ]]; do
  case $1 in
    --token) TOKEN="$2"; shift 2 ;;
    --subnet) SUBNET="$2"; shift 2 ;;
    --action) ACTION="$2"; shift 2 ;;
    *) echo '{"error": "Unknown arg: '"$1"'"}' >&2; exit 1 ;;
  esac
done
[[ -z "$TOKEN" || -z "$SUBNET" || -z "$ACTION" ]] && { echo '{"error": "Missing --token, --subnet, --action"}' >&2; exit 1; }
[[ "$SUBNET" =~ ^[0-9]+$ && "$SUBNET" -gt 0 ]] || { echo '{"error": "Invalid --subnet: must be > 0"}' >&2; exit 1; }
[[ "$ACTION" == "activate" || "$ACTION" == "pause" || "$ACTION" == "resume" ]] || {
  echo '{"error": "--action must be activate, pause, or resume"}' >&2; exit 1
}

# Pre-flight
WALLET_ADDR=$(awp-wallet status --token "$TOKEN" | jq -r '.address')
[[ -z "$WALLET_ADDR" || "$WALLET_ADDR" == "null" ]] && { echo '{"error": "Invalid token"}' >&2; exit 1; }

REGISTRY=$(curl -s "$API_BASE/registry")
AWP_REGISTRY=$(echo "$REGISTRY" | jq -r '.awpRegistry')
[[ -z "$AWP_REGISTRY" || "$AWP_REGISTRY" == "null" ]] && { echo '{"error": "Failed to get contract address from /registry"}' >&2; exit 1; }

# Check current subnet status
SUBNET_INFO=$(curl -s "$API_BASE/subnets/$SUBNET")
STATUS=$(echo "$SUBNET_INFO" | jq -r '.status')
[[ -z "$STATUS" || "$STATUS" == "null" ]] && { echo '{"error": "Subnet #'"$SUBNET"' not found"}' >&2; exit 1; }

# Validate state transition
case "$ACTION" in
  activate)
    [[ "$STATUS" != "Pending" ]] && { echo '{"error": "Cannot activate: subnet is '"$STATUS"' (must be Pending)"}' >&2; exit 1; }
    # activateSubnet(uint256) selector = 0xcead1c96
    SELECTOR="0xcead1c96"
    ;;
  pause)
    [[ "$STATUS" != "Active" ]] && { echo '{"error": "Cannot pause: subnet is '"$STATUS"' (must be Active)"}' >&2; exit 1; }
    # pauseSubnet(uint256) selector = 0x44e047ca
    SELECTOR="0x44e047ca"
    ;;
  resume)
    [[ "$STATUS" != "Paused" ]] && { echo '{"error": "Cannot resume: subnet is '"$STATUS"' (must be Paused)"}' >&2; exit 1; }
    # resumeSubnet(uint256) selector = 0x5364944c
    SELECTOR="0x5364944c"
    ;;
esac

SUBNET_PADDED=$(python3 -c "print(hex($SUBNET)[2:].zfill(64))")
CALLDATA="${SELECTOR}${SUBNET_PADDED}"

echo '{"step": "'"$ACTION"'Subnet", "subnet": '"$SUBNET"', "currentStatus": "'"$STATUS"'"}' >&2
awp-wallet send --token "$TOKEN" --to "$AWP_REGISTRY" --data "$CALLDATA" --chain base

#!/usr/bin/env bash
# AWP Gasless onboarding — register or bind via relay
#
# Usage:
#   Principal mode (register / set recipient to self):
#     ./relay-start.sh --token <session_token> --mode principal
#
#   Agent mode (bind to a target address):
#     ./relay-start.sh --token <session_token> --mode agent --target <address>
#
# Nonce: fetched from GET /api/nonce/{address}
# EIP-712 domain: fetched from GET /api/registry → eip712Domain
# Signature: 65 bytes (r[32]+s[32]+v[1]), hex with 0x prefix = 132 chars
#
# Prerequisites: awp-wallet (unlocked), curl, jq

set -euo pipefail

API_BASE="${AWP_API_URL:-https://tapi.awp.sh/api}"
TOKEN=""
MODE=""
TARGET=""

while [[ $# -gt 0 ]]; do
  case $1 in
    --token) TOKEN="$2"; shift 2 ;;
    --mode) MODE="$2"; shift 2 ;;
    --target) TARGET="$2"; shift 2 ;;
    --principal) MODE="principal"; shift 1 ;;
    --api) API_BASE="$2"; shift 2 ;;
    *) echo '{"error": "Unknown arg: '"$1"'"}' >&2; exit 1 ;;
  esac
done

[[ -z "$TOKEN" ]] && { echo '{"error": "Missing --token"}' >&2; exit 1; }
[[ -z "$MODE" ]] && { echo '{"error": "Missing --mode (principal or agent)"}' >&2; exit 1; }
[[ "$MODE" != "principal" && "$MODE" != "agent" ]] && { echo '{"error": "--mode must be principal or agent"}' >&2; exit 1; }
[[ "$MODE" == "agent" && -z "$TARGET" ]] && { echo '{"error": "Agent mode requires --target <address>"}' >&2; exit 1; }
[[ -n "$TARGET" && ! "$TARGET" =~ ^0x[0-9a-fA-F]{40}$ ]] && { echo '{"error": "Invalid --target: must be 0x + 40 hex chars"}' >&2; exit 1; }

# Step 1: Fetch registry + eip712Domain
REGISTRY=$(curl -s "$API_BASE/registry") || { echo '{"error": "Failed to fetch /registry"}' >&2; exit 1; }

# Read eip712Domain from registry (new V2 API)
EIP712_NAME=$(echo "$REGISTRY" | jq -r '.eip712Domain.name // empty')
EIP712_VERSION=$(echo "$REGISTRY" | jq -r '.eip712Domain.version // empty')
EIP712_CHAIN_ID=$(echo "$REGISTRY" | jq -r '.eip712Domain.chainId // empty')
EIP712_CONTRACT=$(echo "$REGISTRY" | jq -r '.eip712Domain.verifyingContract // empty')

# Fallback: if eip712Domain not present, construct from registry fields
if [[ -z "$EIP712_NAME" || "$EIP712_NAME" == "null" ]]; then
  EIP712_CONTRACT=$(echo "$REGISTRY" | jq -r '.awpRegistry')
  [[ -z "$EIP712_CONTRACT" || "$EIP712_CONTRACT" == "null" ]] && { echo '{"error": "Cannot determine contract address from /registry"}' >&2; exit 1; }
  EIP712_CHAIN_ID=$(echo "$REGISTRY" | jq -r '.chainId // empty')
  [[ -z "$EIP712_CHAIN_ID" || "$EIP712_CHAIN_ID" == "null" ]] && { echo '{"error": "Cannot determine chainId from /registry"}' >&2; exit 1; }
  EIP712_NAME="AWPRegistry"
  EIP712_VERSION="1"
  echo '{"info": "eip712Domain not in registry, using fallback"}' >&2
fi

echo '{"info": "domain: '"$EIP712_NAME"' v'"$EIP712_VERSION"' chain='"$EIP712_CHAIN_ID"' contract='"$EIP712_CONTRACT"'"}' >&2

# Step 2: Get wallet address
WALLET_ADDR=$(awp-wallet status --token "$TOKEN" | jq -r '.address') || {
  echo '{"error": "Failed to get wallet address"}' >&2; exit 1
}
[[ -z "$WALLET_ADDR" || "$WALLET_ADDR" == "null" ]] && {
  echo '{"error": "Wallet address is empty — token may be expired"}' >&2; exit 1
}

# Step 3: Check current status
CHECK=$(curl -s "$API_BASE/address/$WALLET_ADDR/check") || true
IS_REGISTERED=$(echo "$CHECK" | jq -r '.isRegistered // .isRegisteredUser // false' 2>/dev/null)
BOUND_TO=$(echo "$CHECK" | jq -r '.boundTo // empty' 2>/dev/null)

if [[ "$MODE" == "principal" && "$IS_REGISTERED" == "true" ]]; then
  echo '{"status": "already_registered", "address": "'"$WALLET_ADDR"'"}'
  exit 0
fi
if [[ "$MODE" == "agent" && -n "$BOUND_TO" && "$BOUND_TO" != "null" && "$BOUND_TO" != "" && "$BOUND_TO" != "0x0000000000000000000000000000000000000000" ]]; then
  echo '{"status": "already_bound", "address": "'"$WALLET_ADDR"'", "boundTo": "'"$BOUND_TO"'"}'
  exit 0
fi

# Step 4: Get nonce from /api/nonce/{address}
NONCE_RESP=$(curl -s "$API_BASE/nonce/$WALLET_ADDR") || { echo '{"error": "Failed to fetch nonce"}' >&2; exit 1; }
NONCE=$(echo "$NONCE_RESP" | jq -r '.nonce // empty')
[[ -z "$NONCE" || "$NONCE" == "null" ]] && { echo '{"error": "Invalid nonce response: '"$NONCE_RESP"'"}' >&2; exit 1; }

# Step 5: Deadline (1 hour from now)
DEADLINE=$(( $(date +%s) + 3600 ))

# Step 6: Build EIP-712 typed data and submit
if [[ "$MODE" == "principal" ]]; then
  # Principal mode: setRecipient(self) via /relay/set-recipient
  EIP712_DATA=$(cat <<EIPJSON
{
  "types": {
    "EIP712Domain": [
      {"name": "name", "type": "string"},
      {"name": "version", "type": "string"},
      {"name": "chainId", "type": "uint256"},
      {"name": "verifyingContract", "type": "address"}
    ],
    "SetRecipient": [
      {"name": "user", "type": "address"},
      {"name": "recipient", "type": "address"},
      {"name": "nonce", "type": "uint256"},
      {"name": "deadline", "type": "uint256"}
    ]
  },
  "primaryType": "SetRecipient",
  "domain": {
    "name": "$EIP712_NAME",
    "version": "$EIP712_VERSION",
    "chainId": $EIP712_CHAIN_ID,
    "verifyingContract": "$EIP712_CONTRACT"
  },
  "message": {
    "user": "$WALLET_ADDR",
    "recipient": "$WALLET_ADDR",
    "nonce": $NONCE,
    "deadline": $DEADLINE
  }
}
EIPJSON
)
  RELAY_ENDPOINT="$API_BASE/relay/set-recipient"
  RELAY_BODY="{\"user\": \"$WALLET_ADDR\", \"recipient\": \"$WALLET_ADDR\", \"deadline\": $DEADLINE, \"signature\": \"__SIG__\"}"

else
  # AGENT mode: bind(target) via /relay/bind
  # EIP-712 Bind type: {agent, target, nonce, deadline}
  EIP712_DATA=$(cat <<EIPJSON
{
  "types": {
    "EIP712Domain": [
      {"name": "name", "type": "string"},
      {"name": "version", "type": "string"},
      {"name": "chainId", "type": "uint256"},
      {"name": "verifyingContract", "type": "address"}
    ],
    "Bind": [
      {"name": "agent", "type": "address"},
      {"name": "target", "type": "address"},
      {"name": "nonce", "type": "uint256"},
      {"name": "deadline", "type": "uint256"}
    ]
  },
  "primaryType": "Bind",
  "domain": {
    "name": "$EIP712_NAME",
    "version": "$EIP712_VERSION",
    "chainId": $EIP712_CHAIN_ID,
    "verifyingContract": "$EIP712_CONTRACT"
  },
  "message": {
    "agent": "$WALLET_ADDR",
    "target": "$TARGET",
    "nonce": $NONCE,
    "deadline": $DEADLINE
  }
}
EIPJSON
)
  RELAY_ENDPOINT="$API_BASE/relay/bind"
  RELAY_BODY="{\"agent\": \"$WALLET_ADDR\", \"target\": \"$TARGET\", \"deadline\": $DEADLINE, \"signature\": \"__SIG__\"}"
fi

# Step 7: Sign
SIG_RESULT=$(awp-wallet sign-typed-data --token "$TOKEN" --data "$EIP712_DATA") || {
  echo '{"error": "EIP-712 signing failed"}' >&2; exit 1
}
SIGNATURE=$(echo "$SIG_RESULT" | jq -r '.signature')

# Replace signature placeholder
FINAL_BODY=$(echo "$RELAY_BODY" | sed "s|__SIG__|$SIGNATURE|")

# Step 8: Submit
echo '{"info": "Submitting to '"$RELAY_ENDPOINT"'"}' >&2
RELAY_RESULT=$(curl -s -w "\n%{http_code}" -X POST "$RELAY_ENDPOINT" \
  -H "Content-Type: application/json" \
  -d "$FINAL_BODY")

HTTP_CODE=$(echo "$RELAY_RESULT" | tail -1)
BODY=$(echo "$RELAY_RESULT" | sed '$d')

if [[ "$HTTP_CODE" -ge 200 && "$HTTP_CODE" -lt 300 ]]; then
  echo "$BODY"
else
  echo "$BODY" >&2
  exit 1
fi

#!/usr/bin/env node
/**
 * wallet-raw-call.mjs — 通过 awp-wallet 内部签名发送原始合约调用
 *
 * awp-wallet CLI 的 send 命令只支持代币转账（--to, --amount, --asset），
 * 不支持原始 calldata。此脚本直接使用 awp-wallet 的内部模块（keystore、session、viem）
 * 来签名并发送带有任意 calldata 的交易。
 *
 * 用法:
 *   node wallet-raw-call.mjs --token <session> --to <contract> --data <hex> [--value <wei>]
 *
 * 必须在 awp-wallet 目录下运行（或设置 AWP_WALLET_DIR 环境变量），
 * 以便正确解析 node_modules 和内部模块。
 */

import { parseArgs } from "node:util"
import { resolve, dirname } from "node:path"
import { realpathSync, existsSync } from "node:fs"

// ── 解析命令行参数 ──────────────────────────────────
const { values: args } = parseArgs({
  options: {
    token:  { type: "string" },
    to:     { type: "string" },
    data:   { type: "string" },
    value:  { type: "string", default: "0" },
    chain:  { type: "string", default: "base" },
  },
  strict: true,
})

if (!args.token || !args.to || !args.data) {
  console.error(JSON.stringify({ error: "Required: --token, --to, --data" }))
  process.exit(1)
}

// ── 格式校验 ──────────────────────────────────────────
if (!/^0x[0-9a-fA-F]{40}$/.test(args.to)) {
  console.error(JSON.stringify({ error: `Invalid --to address: ${args.to}` }))
  process.exit(1)
}
if (!/^0x(?:[0-9a-fA-F]{2}){4,}$/.test(args.data)) {
  console.error(JSON.stringify({ error: `Invalid --data hex: ${args.data}` }))
  process.exit(1)
}

// ── 定位 awp-wallet 安装目录 ──────────────────────────
function findAwpWalletDir() {
  // 1. 环境变量
  if (process.env.AWP_WALLET_DIR && existsSync(process.env.AWP_WALLET_DIR)) {
    return process.env.AWP_WALLET_DIR
  }
  // 2. 在 PATH 中查找 awp-wallet 可执行文件（纯 Node.js，无需 child_process）
  const pathDirs = (process.env.PATH || "").split(":")
  for (const dir of pathDirs) {
    const candidate = resolve(dir, "awp-wallet")
    if (existsSync(candidate)) {
      try {
        const real = realpathSync(candidate)
        // real = .../awp-wallet/scripts/wallet-cli.js → 上两级 = awp-wallet/
        return dirname(dirname(real))
      } catch { /* 跳过无法解析的符号链接 */ }
    }
  }
  {
    // 3. 默认路径
    const defaultDir = resolve(process.env.HOME, "awp-wallet")
    if (existsSync(resolve(defaultDir, "scripts/lib/keystore.js"))) return defaultDir
    console.error(JSON.stringify({ error: "Cannot locate awp-wallet installation. Set AWP_WALLET_DIR." }))
    process.exit(1)
  }
}

const AWP_DIR = findAwpWalletDir()

// ── 导入 awp-wallet 内部模块 ─────────────────────────
const { validateSession, requireScope } = await import(`${AWP_DIR}/scripts/lib/session.js`)
const { loadSigner, getAddress } = await import(`${AWP_DIR}/scripts/lib/keystore.js`)
const { resolveChainId, viemChain, publicClient, getRpcUrl } = await import(`${AWP_DIR}/scripts/lib/chains.js`)

const { createWalletClient, http } = await import(`${AWP_DIR}/node_modules/viem/index.js`)

// ── 验证 session ─────────────────────────────────────
try {
  validateSession(args.token)
  requireScope(args.token, "transfer")
} catch (e) {
  console.error(JSON.stringify({ error: `Session error: ${e.message}` }))
  process.exit(1)
}

// ── 构建并发送交易 ───────────────────────────────────
try {
  const chainId = resolveChainId(args.chain)
  const chainObj = viemChain(chainId)
  const { account: signer } = loadSigner()
  if (!signer) {
    console.error(JSON.stringify({ error: "Failed to load signer from keystore" }))
    process.exit(1)
  }

  const walletClient = createWalletClient({
    account: signer,
    chain: chainObj,
    transport: http(getRpcUrl(chainId)),
  })

  const tx = {
    to: args.to,
    data: args.data,
  }

  // 支持发送 ETH（value > 0 的合约调用）
  if (args.value && args.value !== "0") {
    try {
      tx.value = BigInt(args.value)
    } catch {
      console.error(JSON.stringify({ error: `Invalid --value (must be integer wei): ${args.value}` }))
      process.exit(1)
    }
  }

  const hash = await walletClient.sendTransaction(tx)

  // 等待确认
  const client = publicClient(chainId)
  const receipt = await client.waitForTransactionReceipt({
    hash,
    timeout: 90_000,
    confirmations: 1,
  })

  console.log(JSON.stringify({
    status: receipt.status === "success" ? "confirmed" : "reverted",
    txHash: hash,
    chain: chainObj.name,
    chainId,
    to: args.to,
    gasUsed: receipt.gasUsed.toString(),
    blockNumber: Number(receipt.blockNumber),
  }))
} catch (e) {
  console.error(JSON.stringify({ error: `Transaction failed: ${e.message}` }))
  process.exit(1)
}
